const app=document.querySelector<HTMLDivElement>('#app')!;
const races=['human','zombie','orc','elf'];
const store={get<T>(k:string,f:T):T{try{return JSON.parse(localStorage.getItem('mt-'+k)||'null')??f;}catch{return f;}},set(k:string,v:any){try{localStorage.setItem('mt-'+k,JSON.stringify(v));}catch{}}};
let profile=loadProfile(store.get<any>('profile-v7',null));
function persistProfile(next:Profile){localStorage.setItem('mt-profile-v7',JSON.stringify(next));profile=next;}
// The full original catalogue has ~1,500 monsters; the collection shows them a page at a time so phones stay responsive.
const COLLECTION_PAGE=60;let collectionLimit=COLLECTION_PAGE,collectionKey='',shopLimit=COLLECTION_PAGE,shopKey='';
let catalogMode='owned',filterRarity='all',shopRace='all',shopRarity='all',shopType='all';
let settings=store.get('settings',{sound:true,speed:650,timer:false});
const heroInfo=(r:string,source=true)=>source?{...leaders[r],...nativeHeroes[r],text:r.startsWith('hero_')?(nativeHeroes[r]?.abilityId?`${nativeHeroes[r].ability} (${nativeHeroes[r].cost} موجو): ${(abilities as any)[nativeHeroes[r].abilityId!]?.description||''}`:'بلا قدرة خاصة.'):r==='orc'?'هجوم مدفعية بمدى 3، وحركة أو هجوم في الدور.':r==='human'?'قدرة تعطّش الدم: +2 قوة لكل عدو مجاور، بتكلفة 2 موجو.':r==='zombie'?'اسحب بطاقة مقابل 2 موجو بدل الهجوم.':'عالج صديقًا 3 صحة مقابل 2 موجو بدل الهجوم.'}:leaders[r];
type SavedDeck={id:string,name:string,hero:string,cards:string[],rule:DeckRule};
let savedDecks=store.get<SavedDeck[]>('saved-decks',[]);
if(!savedDecks.length){for(const hero of races){const old=store.get<string[]|null>('deck-'+hero,null);if(old)savedDecks.push({id:'migrated-'+hero,name:'مجموعتي • '+raceNames[hero],hero,cards:old,rule:'standard'});}store.set('saved-decks',savedDecks);}
let buildingId='',buildingName='',builderReturn='menu',inspectedCard='';
let handOffset=0,deckRule:DeckRule=store.get('deck-rule','standard');
let opts={rewardEligible:false,enemyDeck:'zombie',deckId:store.get('selected-deck','starter'),race:'human',enemy:'zombie',map:'native',difficulty:store.get<string>('difficulty','hard'),mode:'ai',stage:0,originalRules:true};
let state:GameState|undefined,scene:Arena|undefined,selectedUnit:number|undefined,selectedCard:number|undefined,monsterAbility=false,ability=false,teleport=false,aiTimer:any,timer:any,seconds=60,history:GameState[]=[];
let mulligan=new Set<number>(),screen='menu',buildingRace='human',buildingDeck:string[]=[],filterRace='all',filterType='all',filterCost='all',toastTimer:any,busy=false,modalOpen=false,runId=0,stageProgress=store.get('progress',0);
function sound(type='click'){if(!settings.sound)return;try{const file=type==='attack'?'castspell':type==='summon'?'addcard':'grabcard';const a=new Audio(originalUrl('audio/'+file+'.wav'));a.volume=.25;a.play().catch(()=>{});}catch{}}
function toast(text:string){document.querySelector('#toast')?.remove();const el=document.createElement('div');el.id='toast';el.textContent=text;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3200);}
const button=(id:string,t:string,cls='')=>`<button data-do="${id}" class="${cls}">${t}</button>`;
const raceImg=(race:string)=>artUrl('LEADER_'+race);
function cleanup(){monsterAbility=false;runId++;clearTimeout(aiTimer);clearInterval(timer);scene?.game?.destroy(true);scene=undefined;busy=false;modalOpen=false;document.querySelector('#dialog')?.remove();document.querySelector('#card-detail')?.remove();}
const ui=(name:string)=>originalUrl('ui-v7/'+name+'.webp');
function wallet(){return `<span class="wallet"><img src="${ui('coin')}" alt="عملة"><b>${profile.coins}</b><small>ذهب</small></span>`;}
function book(title:string,left:string,right:string){return `<main class="book-world"><header class="book-top"><span>نسخة شخصية • ٧</span>${wallet()}</header><article class="open-book"><section class="book-leaf book-left" dir="rtl"><img class="native-wordmark" src="${ui('wordmark')}" alt="Combat Monsters"><h1>${title}</h1>${left}</section><section class="book-leaf book-right" dir="rtl">${right}</section><i class="book-spine"></i></article><footer class="book-foot">وحوش المعركة • حفظ التقدم على هذا المتصفح</footer></main>`;}
function starterScreen(){cleanup();screen='starter';app.innerHTML=book('اختر مجموعة البداية',`<p class="book-intro">ابدأ بمجموعة من ٣٠ بطاقة، ثم اجمع البقية بالانتصارات والعملات.</p><ul class="book-rules"><li>مجموعة واحدة مجانية من عرق تختاره.</li><li>كل فوز ضد الكمبيوتر: بطاقة عشوائية و${WIN_COINS} عملة.</li><li>كلما ارتفعت الندرة، قل ظهورها وارتفع سعرها.</li></ul><p>معك <b>١٠٠ عملة</b> في البداية. القادة الأربعة متاحون، واختيار القائد مستقل عن أعراق بطاقاتك.</p>`,`<h2>مجموعتك الأولى</h2><div class="starter-grid">${races.map(r=>`<button class="starter-choice" data-starter="${r}"><img src="${raceImg(r)}" alt=""><strong>${raceNames[r]}</strong><small>٣٠ بطاقة • عادي وغير شائع</small></button>`).join('')}</div><p class="paper-note">التدريب يستخدم بطاقات مُعارة، ولا يفتحها في مجموعتك.</p>`);}
const DAILY_COINS=250;
const todayKey=()=>new Date().toLocaleDateString('en-CA');
/** Today's challenge: the same opponent and original arena for everyone on this date. */
function dailyChallenge(){const day=todayKey();let h=2166136261;for(const ch of day)h=Math.imul(h^ch.charCodeAt(0),16777619)>>>0;const enemy=races[h%races.length];opts.mode='daily';opts.originalRules=true;opts.enemy=enemy;opts.enemyDeck=enemy;opts.map=nativeMapIds[(h>>>8)%nativeMapIds.length];const d=chosenDeck(),error=playableError(profile,d.cards,opts.race,d.rule);if(error){toast(error);setup();return;}startMatch();}
function menu(){cleanup();if(!profile.starterRace){starterScreen();return;}screen='menu';const save=store.get<any>('battle',null);app.innerHTML=book('وحوش المعركة',`<p class="book-intro">استدعِ وحوشك، وابنِ مجموعتك بطاقة بعد بطاقة.</p><div class="collection-totals"><div><b>${Object.keys(profile.inventory).length}<small> / ${cards.length}</small></b><span>بطاقات مختلفة</span></div><div><b>${profile.wins}</b><span>انتصارات</span></div></div><h3>غنائم الانتصار</h3><p>كل فوز ضد الكمبيوتر يمنحك <b>${WIN_COINS} عملة وبطاقة عشوائية</b>. قد تحصل على نسخة مكررة.</p><div class="drop-summary">${rarityOrder.map(r=>`<span style="color:${rarityInfo[r].color}"><b>${rarityInfo[r].weight}%</b>${rarityInfo[r].name}</span>`).join('')}</div><small>هذه نسب موازنة نسختنا. التدريب واللعب المحلي بلا مكافآت.</small>${save?button('continue','متابعة المعركة المحفوظة ←','primary'):''}`,`<h2>لاعب واحد</h2><p class="book-click">اضغط للبدء</p><div class="book-mode-grid original-modes"><button data-do="daily" class="${store.get('daily-claimed','')===todayKey()?'daily-done':''}"><img src="${ui('menu-daily')}" alt=""><strong>تحدي اليوم</strong><small>${store.get('daily-claimed','')===todayKey()?'أخذت جائزة اليوم • تقدر تعيده':'خصم وساحة جديدة كل يوم • +'+DAILY_COINS+' عملة'}</small></button><button data-do="quests"><img src="${ui('menu-solo')}" alt=""><strong>المهمات الفردية</strong><small>Solo Quests • ${QUESTS.reduce((n,q)=>n+questWon(profile,q.id).length,0)} / ${QUESTS.reduce((n,q)=>n+q.rooms.length,0)} معركة</small></button><button data-do="setup"><img src="${ui('menu-skirmish')}" alt=""><strong>المناوشة</strong><small>معركة ضد الكمبيوتر</small></button><button data-do="passplay"><img src="${ui('menu-passplay')}" alt=""><strong>العب مع صديق</strong><small>Pass &amp; Play • على نفس الجهاز</small></button></div><div class="book-icon-row"><button data-do="decks" title="مجموعتي"><img src="${ui('icon-cards')}" alt=""><span>مجموعتي</span></button><button data-do="shop" title="المتجر"><img src="${ui('icon-shop')}" alt=""><span>المتجر</span></button><button data-do="chests" title="صناديقي" class="chest-icon"><img src="${ui('chest-full')}" alt="">${CHEST_TYPES.reduce((n,t)=>n+chestCount(profile,t),0)?`<i>${CHEST_TYPES.reduce((n,t)=>n+chestCount(profile,t),0)}</i>`:''}<span>صناديقي</span></button><button data-do="settings" title="الإعدادات"><img src="${ui('icon-settings')}" alt=""><span>الإعدادات</span></button><button data-do="help" title="قواعد اللعبة"><img src="${ui('icon-trophy')}" alt=""><span>القواعد</span></button></div><div class="book-training">${button('tutorial','تعلّم اللعب')}${button('runes-tutorial','تدريب الرون')}${button('ability-tutorial','قدرات الوحوش')}</div>`);}
function shop(){cleanup();screen='shop';app.innerHTML=`<main class="page shop-page"><header class="page-header">${button('menu','← الكتاب','back')}<div><div class="eyebrow">بطاقات مقابل العملات المكتسبة</div><h2>متجر البطاقات</h2></div>${wallet()}</header><p class="shop-note">تشتري نسخة واحدة بالسعر الظاهر، وتُضاف مباشرة إلى مجموعتك. كل فوز ضد الكمبيوتر يمنح ${WIN_COINS} عملة وبطاقة عشوائية.</p><button data-do="chests" class="shop-chests"><img src="${ui('chest-full')}" alt=""><span><strong>صناديق البطاقات</strong><small>صغير، كامل، وحوش، معدات، رونات، تعاويذ، ضخم • افتحها واكسب بطاقات عشوائية</small></span></button><div class="price-legend">${rarityOrder.map(r=>`<span><b style="color:${rarityInfo[r].color}">${rarityInfo[r].name}</b> ${rarityInfo[r].price} <img src="${ui('coin')}" alt="عملة"><small>فرصة المكافأة ${rarityInfo[r].weight}%</small></span>`).join('')}</div><div class="shop-filters"><select id="shop-rarity"><option value="all">كل الندرات</option>${rarityOrder.map(r=>`<option value="${r}" ${shopRarity===r?'selected':''}>${rarityInfo[r].name}</option>`).join('')}</select><select id="shop-race"><option value="all">كل الأعراق</option>${[...monsterRaces,'neutral'].map(r=>`<option value="${r}" ${shopRace===r?'selected':''}>${raceNames[r]}</option>`).join('')}</select><select id="shop-type">${typeFilters.map(([v,n])=>`<option value="${v}" ${v===shopType?'selected':''}>${n}</option>`).join('')}</select></div><div class="shop-grid">${(()=>{const list=cards.filter(c=>(shopRarity==='all'||cardRarity(c)===shopRarity)&&(shopRace==='all'||c.race===shopRace)&&typeMatch(c,shopType));const key=shopRarity+'|'+shopRace+'|'+shopType;if(key!==shopKey){shopKey=key;shopLimit=COLLECTION_PAGE;}return list.slice(0,shopLimit).map(c=>`<article class="shop-item">${cardHTML(c.id,-3)}<div class="shop-copy"><span>${rarityInfo[cardRarity(c)].name}</span><small>تملك ${ownedCount(profile,c.id)} نسخة</small></div><button data-buy="${c.id}" ${profile.coins<cardPrice(c)||ownedCount(profile,c.id)>=4?'disabled':''}>${ownedCount(profile,c.id)>=4?'لديك ٤ نسخ':`شراء • ${cardPrice(c)} <img src="${ui('coin')}" alt="عملة">`}</button></article>`).join('')+(list.length>shopLimit?button('more-shop',`عرض المزيد • ${list.length-shopLimit} بطاقة متبقية`,'more-cards'):'');})()}</div></main>`;}
function buy(id:string){const result=purchaseCard(profile,id);if(result.error){toast(result.error);return;}try{persistProfile(result.profile);}catch{toast('تعذر حفظ الشراء؛ لم يتغير رصيدك');return;}toast('اشتريت '+cardById[id].name);shop();}
function chosenDeck(){if(opts.deckId==='starter'||!opts.deckId)return {id:'starter',name:'مجموعة البداية',hero:opts.race,cards:[...profile.starterDeck],rule:'standard' as DeckRule};const saved=savedDecks.find(d=>d.id===opts.deckId);const race=opts.deckId.startsWith('preset:')?opts.deckId.slice(7):'human';return saved?{...saved,cards:[...saved.cards]}:{id:'preset:'+race,name:'تشكيلة '+(raceNames[race]||raceNames.human),hero:opts.race,cards:formatStarterDeck(monsterRaces.includes(race)?race:'human',deckRule,true),rule:deckRule};}
function deckSummary(ids:string[]){const counts:Record<string,number>={};for(const id of ids){const c=cardById[id];if(c?.type==='unit')counts[c.race]=(counts[c.race]||0)+1;}return Object.entries(counts).map(([r,n])=>`<span>${raceNames[r]} <b>${n}</b></span>`).join('');}
function deckPicker(){const d=chosenDeck(),error=playableError(profile,d.cards,opts.race,opts.originalRules===false?'legacy':d.rule);return `<section class="prebattle-deck"><div class="eyebrow">تشكيلتك قبل المعركة</div><h3>اختر مجموعة بطاقاتك</h3><label>المجموعة<select id="match-deck"><option value="starter" ${opts.deckId==='starter'?'selected':''}>مجموعة البداية • ٣٠ بطاقة</option><optgroup label="مجموعاتي المحفوظة">${savedDecks.map(x=>`<option value="${x.id}" ${opts.deckId===x.id?'selected':''}>${escapeHTML(x.name)} • ${x.cards.length} بطاقة</option>`).join('')}</optgroup><optgroup label="خطط الأعراق • تحتاج امتلاك بطاقاتها">${monsterRaces.map(r=>`<option value="preset:${r}" ${opts.deckId==='preset:'+r?'selected':''}>${raceNames[r]}</option>`).join('')}</optgroup></select></label><div class="chosen-deck-meta"><strong>${d.cards.length} بطاقة</strong><span>${({standard:'عادي',singleton:'فريد',tribal:'قبلي',pauper:'بسيط',hordes:'حشود',legacy:'قديم'})[d.rule]}</span></div><div class="deck-race-summary">${deckSummary(d.cards)}</div><p class="validation ${error?'invalid':''}">${error||'✓ جاهزة للمعركة'}</p><div class="deck-secondary">${button('edit-match-deck','تعديل هذه التشكيلة')}${button('new-match-deck','تشكيلة جديدة')}</div><small>القائد مستقل عن أعراق الوحوش. يمكنك خلط الأعراق في النمط العادي.</small></section>`;}


// ---- Booster chests ----
function chests(){cleanup();screen='chests';const total=CHEST_TYPES.reduce((n,t)=>n+chestCount(profile,t),0);app.innerHTML=`<main class="page chest-page"><header class="page-header">${button('menu','← الرئيسية','back')}<div><div class="eyebrow">Booster Chests • ${total} صندوق</div><h2>صناديقي</h2></div>${wallet()}</header><p class="page-intro">مثل اللعبة الأصلية: الصناديق فيها بطاقات عشوائية. تكسبها من زعماء المهمات الفردية وتحدي اليوم، وتقدر تشتري بعضها بالعملات.</p><div class="chest-grid">${CHEST_TYPES.map(t=>{const c=CHESTS[t],n=chestCount(profile,t);return `<article class="chest-card ${n?'owned':''}"><img src="${ui('chest-'+t)}" alt=""><span class="chest-count">${n}</span><h3>${c.name}</h3><small>${c.english}</small><p>${c.text}</p><div class="chest-actions">${n?`<button class="primary" data-open-chest="${t}">افتح</button>`:''}${c.price?`<button data-buy-chest="${t}" ${profile.coins<c.price?'disabled':''}><img src="${ui('coin')}" alt=""> ${c.price}</button>`:`<span class="earn-only">${t==='mystery'?'جائزة تحدي اليوم':'جائزة زعيم مهمة الكابوس'}</span>`}</div></article>`;}).join('')}</div></main>`;}
function openChestUI(t:ChestType){const r=openChest(profile,t);if(r.error||!r.opened){toast(r.error||'تعذر الفتح');return;}const before=profile;try{persistProfile(r.profile);}catch{toast('تعذر حفظ الصندوق');return;}const o=r.opened;sound('reward');
 const body=`<div class="chest-open"><img class="chest-shake" src="${ui('chest-'+t)}" alt=""><div class="chest-loot">${o.cards.map((id,i)=>`<div class="loot-card" style="--i:${i}">${ownedCount(before,id)?'':'<b class="new-tag">جديدة!</b>'}${cardHTML(id,-5)}</div>`).join('')}${o.coins?`<div class="reward-coins loot-coins"><img src="${ui('coin')}" alt="عملة"> +${o.coins}</div>`:''}${o.chests.map(c=>`<div class="loot-chest"><img src="${ui('chest-'+c)}" alt=""><p>رهيب، طلع لك صندوق ثاني: ${CHESTS[c].name}!</p></div>`).join('')}</div></div>`;
 dialog(CHESTS[t].name,body,[...(chestCount(profile,t)?[{text:`افتح ثاني (${chestCount(profile,t)})`,fn:()=>openChestUI(t)}]:[]),{text:'صناديقي',fn:chests},{text:'مجموعتي',fn:()=>deckBuilder()}]);}
// ---- Solo quests ----
let questId=store.get<string>('quest-id','easy'),questRoom=1;
const questMapArt=(q:Quest)=>ui('quest-map-'+(QUESTS.indexOf(q)%6+1));
function quests(){cleanup();screen='quests';app.innerHTML=`<main class="page quest-page"><header class="page-header">${button('menu','← الرئيسية','back')}<div><div class="eyebrow">Solo Quests</div><h2>المهمات الفردية</h2></div>${wallet()}</header><p class="page-intro">مهمات اللعبة الأصلية بغرفها وأبطالها وتشكيلاتها وساحاتها. كل غرفة تفوز فيها تفتح الغرف اللي بعدها، وأول فوز في كل غرفة يعطيك جائزة. الزعماء يعطون بطاقة نادرة، والمعركة الأخيرة بطاقة أسطورية.</p><div class="quest-list">${QUESTS.map(q=>{const open=questOpen(profile,q),won=questWon(profile,q.id).length,done=questComplete(profile,q);return `<button class="quest-card ${open?'':'locked'} ${done?'done':''}" data-quest="${q.id}" ${open?'':'disabled'} style="--map:url('${questMapArt(q)}')"><span class="quest-progress">${won} / ${q.rooms.length}</span><h3>${q.title}</h3><small>${q.english}${q.enemyBonusMojo?' • العدو +'+q.enemyBonusMojo+' موجو كل دور':''}</small><p>${q.text}</p><span class="quest-state">${done?'✓ مكتملة':open?'ادخل الخريطة ←':'🔒 أكمل المهمة السابقة'}</span></button>`;}).join('')}</div></main>`;}
function questMap(id=questId){cleanup();const q=questById[id]||QUESTS[1];questId=q.id;store.set('quest-id',q.id);screen='quest-map';opts.mode='quest';opts.originalRules=true;const won=questWon(profile,q.id),xs=q.rooms.map(r=>r.x),ys=q.rooms.map(r=>r.y),x0=Math.min(...xs),y0=Math.min(...ys),cols=Math.max(...ys)-y0+1,rows=Math.max(...xs)-x0+1;
 // The original lays rooms out west→east; on the portrait parchment east runs downwards.
 const at=(r:QuestRoom)=>({left:(r.y-y0+.5)/cols*80+10,top:(r.x-x0+.5)/rows*84+8});
 const lines=q.rooms.filter(r=>r.parent!==null).map(r=>{const p=q.rooms.find(x=>x.n===r.parent)!,a=at(p),b=at(r);return `<line class="${won.includes(r.n)?'won':roomOpen(profile,q,r)?'open':''}" x1="${a.left}" y1="${a.top}" x2="${b.left}" y2="${b.top}"/>`;}).join('');
 const rooms=q.rooms.map(r=>{const st=won.includes(r.n)?'won':roomOpen(profile,q,r)?'open':'locked',p=at(r);return `<button class="quest-room ${st} ${r.boss||''}" data-room="${r.n}" style="left:${p.left}%;top:${p.top}%" title="${escapeHTML(nativeHeroes[r.hero]?.name||r.hero)}"><img class="orb" src="${ui(r.boss?'quest-orb-red':'quest-orb-green')}" alt=""><img class="hero" src="${raceImg(r.hero)}" alt=""><b>${r.n}</b>${st==='won'?`<img class="mark" src="${ui('quest-check')}" alt="✓">`:st==='locked'?`<img class="mark" src="${ui('quest-lock')}" alt="🔒">`:''}</button>`;}).join('');
 app.innerHTML=`<main class="page quest-map-page"><header class="page-header">${button('quests','← المهمات','back')}<div><div class="eyebrow">${q.english} • ${won.length} / ${q.rooms.length}</div><h2>${q.title}</h2></div>${wallet()}</header><div class="quest-map-layout"><section class="quest-board" style="--map:url('${questMapArt(q)}')"><svg viewBox="0 0 100 100" preserveAspectRatio="none">${lines}</svg>${rooms}</section><aside class="quest-side"><h3>قائدك</h3><div class="quest-heroes">${races.map(r=>`<button class="race-choice ${opts.race===r?'active':''}" data-race="${r}"><img src="${raceImg(r)}" alt=""><strong>${heroInfo(r).name}</strong></button>`).join('')}</div>${deckPicker()}<ul class="quest-legend"><li><img src="${ui('quest-orb-green')}" alt="">معركة</li><li><img src="${ui('quest-orb-red')}" alt="">زعيم (جائزة بطاقة)</li><li><img src="${ui('quest-check')}" alt="">فزت فيها</li><li><img src="${ui('quest-lock')}" alt="">افتحها بالفوز في الغرفة اللي قبلها</li></ul></aside></div></main>`;}
function roomDialog(n:number){const q=questById[questId],r=q.rooms.find(x=>x.n===n);if(!r)return;if(!roomOpen(profile,q,r)){toast('افتح هذه الغرفة بالفوز في الغرفة اللي قبلها');return;}const h=nativeHeroes[r.hero],first=!questWon(profile,q.id).includes(n),prize=questPrize(q,r),units=r.deck.filter(id=>cardById[id]?.type==='unit').length;
 dialog(`${r.boss==='last'?'المعركة الأخيرة':r.boss==='sub'?'زعيم':'معركة'} ${n} • ${q.title}`,`<div class="room-info"><img class="room-hero" src="${raceImg(r.hero)}" alt=""><div><h3>${escapeHTML(h.name)}</h3><p class="room-stats"><span>⚔ ${h.attack}</span><span>♥ ${h.health}</span>${h.armor?`<span>🛡 ${h.armor}</span>`:''}<span>موجو ${h.mojo}${q.enemyBonusMojo?' +'+q.enemyBonusMojo:''} كل دور</span></p><p>${heroInfo(r.hero).text}</p><p class="room-deck">تشكيلته: ${r.deck.length} بطاقة • ${units} وحش • ساحة أصلية من المهمة</p></div></div><div class="room-prize">${first?`<strong>جائزة أول فوز:</strong> <img src="${ui('coin')}" alt=""> ${prize.coins}${prize.chest?` + ${CHESTS[prize.chest].name}`:''}`:'فزت بها من قبل • تقدر تعيدها، وتاخذ غنائم الانتصار العادية'}</div>`,[{text:'ابدأ المعركة',fn:()=>{questRoom=n;opts.mode='quest';opts.enemy=r.hero;opts.map=r.map;opts.difficulty=q.ai;opts.originalRules=true;startMatch();}},{text:'رجوع',fn:()=>{}}]);}
function setup(mode='ai'){opts.originalRules=true;screen='setup';opts.mode=mode;app.innerHTML=`<main class="page setup-page"><header class="page-header">${button('menu','← الرئيسية','back')}<div><div class="eyebrow">جهّز ساحة المعركة</div><h2>${mode==='local'?'لاعبان على نفس الجهاز':'معركة جديدة'}</h2></div><div></div></header><div class="setup-layout"><section class="setup-main"><h3>اختر قائدك <small>التشكيلة تستخدم بطاقاتك المملوكة</small></h3><div class="race-grid">${races.map(r=>`<button class="race-choice ${opts.race===r?'active':''}" data-race="${r}"><img src="${raceImg(r)}" alt=""><span class="race-tag ${r}">${raceNames[r]}</span><strong>${heroInfo(r).name}</strong><small>${heroInfo(r).ability}</small></button>`).join('')}</div><div class="setup-controls"><label>قائد الخصم<select id="enemy">${races.map(r=>`<option value="${r}" ${opts.enemy===r?'selected':''}>${heroInfo(r).name} • ${raceNames[r]}</option>`).join('')}</select></label><label>تشكيلة الخصم<select id="enemy-deck">${monsterRaces.map(r=>`<option value="${r}" ${opts.enemyDeck===r?'selected':''}>${raceNames[r]}</option>`).join('')}</select></label><label>الصعوبة<select id="difficulty" ${mode==='local'?'disabled':''}><option value="easy" ${opts.difficulty==='easy'?'selected':''}>سهل • للتعلّم، قرارات مرنة</option><option value="normal" ${opts.difficulty==='normal'?'selected':''}>عادي • تشكيلة البداية</option><option value="hard" ${opts.difficulty==='hard'?'selected':''}>صعب • يخطط دوره ويتوقع ردك، تشكيلة محاربين قدامى</option><option value="expert" ${opts.difficulty==='expert'?'selected':''}>خبير • تشكيلة أبطال (نادرة وأسطورية) و+1 موجو كل دور</option></select></label><label>نمط اللعب<select id="mode"><option value="ai" ${mode==='ai'?'selected':''}>ضد الكمبيوتر</option><option value="local" ${mode==='local'?'selected':''}>لاعبان على نفس الجهاز</option></select></label></div><h3>اختر الخريطة</h3><div class="map-grid"><button class="map-option native-option ${opts.map==='native'?'active':''}" data-map="native"><div class="map-preview map-native"><span>⬢</span></div><strong>الساحات الأصلية</strong><small>خريطة عشوائية من 108 خرائط اللعبة الأصلية، في ساحة الحمم أو الغابة أو الجبل أو الصحراء</small></button>${maps.map((m,i)=>`<button class="map-option ${opts.map===m.id?'active':''}" data-map="${m.id}"><div class="map-preview map-${i}"><span>${['✦','≈','♜','☀'][i]}</span></div><strong>${m.name}</strong><small>${m.subtitle}</small></button>`).join('')}</div></section><aside class="setup-aside"><div class="eyebrow">قائد مجموعتك</div><h2>${heroInfo(opts.race).name}</h2><p>${heroInfo(opts.race).text}</p>${deckPicker()}<button data-do="start" class="primary large" ${playableError(profile,chosenDeck().cards,opts.race,chosenDeck().rule)?'disabled':''}>ابدأ المعركة ←</button><p class="small-note">نفس الموارد والقوانين لك وللخصم في جميع مستويات الصعوبة.</p></aside></div></main>`;}
function campaign(){screen='campaign';app.innerHTML=`<main class="page"><header class="page-header">${button('menu','← الرئيسية','back')}<div><div class="eyebrow">خمس مواجهات متصاعدة</div><h2>رحلة القادة</h2></div><span>${Math.min(stageProgress,5)} / 5 مكتملة</span></header><p class="page-intro">اختر قبيلتك من «معركة جديدة»، ثم اختبر مجموعتك في هذه المواجهات. تُحفظ المراحل التي تجتازها.</p><div class="campaign-grid">${['حارس الوادي','نداء القبور','عبور المستنقع','حصار الأبراج','آخر القادة'].map((n,i)=>`<button data-stage="${i}" class="campaign-card ${i>stageProgress?'locked':''}" ${i>stageProgress?'disabled':''}><span class="stage-number">0${i+1}</span><img src="${raceImg(races[(i+1)%4])}" alt=""><small>${['سهل','عادي','عادي','صعب','صعب'][i]} • ${maps[i%3].name}</small><h3>${n}</h3><span>${i<stageProgress?'✓ مكتملة':i===stageProgress?'ابدأ المواجهة ←':'🔒 أكمل المرحلة السابقة'}</span></button>`).join('')}</div></main>`;}
function tutorial(){opts.deckId='preset:human';deckRule='standard';opts.mode='tutorial';opts.difficulty='easy';opts.enemy='zombie';opts.race='human';opts.map='river';dialog('تعلّم اللعب في ثلاث خطوات',`<div class="help-steps"><p><b>١ • استدعِ مقاتلًا</b>اضغط بطاقة في يدك، ثم خانة خضراء بجوار قائدك. في القواعد الأقرب للأصل يستطيع الجديد الهجوم فورًا، ويتحرك من دوره التالي.</p><p><b>٢ • تحرّك وتمركز</b>اضغط وحدة ثم خانة زرقاء. قف على النجمة لهجوم +2، أو الدرع لدفاع +2. الرموز تبقى في مكانها.</p><p><b>٣ • هاجم قائد الخصم</b>الأعداء في المدى يضيئون بالأحمر. الهجوم الأساسي مجاني بالموجو؛ أما تكلفة القدرة الخاصة فتظهر على زرها.</p></div>`,[{text:'ابدأ المباراة التعليمية',fn:()=>startMatch()},{text:'رجوع',fn:()=>{}}]);}
function startMatch(restore?:any){if(!restore&&!['tutorial','runes','abilities'].includes(opts.mode)){const d=chosenDeck(),error=playableError(profile,d.cards,opts.race,opts.originalRules===false?'legacy':d.rule);if(error){toast(error);opts.mode==='quest'?questMap():setup(opts.mode);return;}}cleanup();screen='battle';history=[];mulligan.clear();selectedUnit=selectedCard=undefined;monsterAbility=false;handOffset=0;monsterAbility=false;ability=false;teleport=false;if(restore){state=upgradeState(restore.state);opts={...opts,...restore.opts,rewardEligible:!!restore.state.matchId&&!!restore.opts.rewardEligible};}else {const seed=Math.floor(Math.random()*2147483647);const choice=chosenDeck(),rule=opts.originalRules===false?'legacy':choice.rule;deckRule=choice.rule;const room=opts.mode==='quest'?questById[questId]?.rooms.find(r=>r.n===questRoom):undefined;state=newGame(seed,choice.cards,opts.race,room?[...room.deck]:(rule==='standard'&&opts.originalRules!==false&&races.includes(opts.enemyDeck||opts.enemy)?aiDeck(opts.enemyDeck||opts.enemy,opts.difficulty):formatStarterDeck(opts.enemyDeck||opts.enemy,rule,opts.originalRules!==false)),opts.enemy,opts.map==='native'?nativeMapIds[Math.floor(Math.random()*nativeMapIds.length)]:opts.map,opts.originalRules!==false,rule,true);state.matchId=Date.now().toString(36)+'-'+Array.from(crypto.getRandomValues(new Uint32Array(4))).map(n=>n.toString(36)).join('-');if(room){state.quest={id:questId,room:room.n};state.mojoBonus=[0,questById[questId].enemyBonusMojo];}else if(opts.difficulty==='expert'&&opts.mode!=='local')state.mojoBonus=[0,1];opts.rewardEligible=['ai','campaign','daily','quest'].includes(opts.mode);if(opts.mode==='tutorial'||opts.mode==='runes'){state.starting=0;state.players[0].hand=opts.mode==='runes'?['R03','R01','R04','H01','A01','S01']:['H01','H02','H03','S01'];state.players[0].deck=formatStarterDeck('human','standard',true);for(const id of state.players[0].hand){const index=state.players[0].deck.indexOf(id);if(index>=0)state.players[0].deck.splice(index,1);}leader(state,1)!.health=15;}}
 if(!restore&&opts.mode==='abilities')configureAbilityLesson(state!);
 app.innerHTML=`<main id="battle"><button class="gear-button" data-do="pause" title="خيارات التوقف" aria-label="خيارات التوقف"></button><header class="battle-header"><div class="battle-brand"><span class="brand-mark">✦</span><strong>وحوش المعركة</strong><span class="divider"></span><small>${maps.find(m=>m.id===state!.mapId)?.name||({lava:'ساحة الحمم',forest:'ساحة الغابة',mountain:'ساحة الجبل',desert:'ساحة الصحراء'} as Record<string,string>)[state!.arena||'']||''}</small></div><div id="turn-label"></div><div class="battle-tools">${button('log','☷ السجل')}${button('help','؟')}${button('sound',settings.sound?'♫':'♩')}${button('pause','☰')}</div></header><div class="battle-area"><aside id="player-hud" class="side-hud"></aside><section class="arena-wrap"><div id="opponent-hand"></div><div id="rune-status"></div><div id="board"></div><div id="hover-info" hidden></div><div id="unit-inspector" hidden></div><div class="camera-tools"><button data-do="zoom-in" title="تقريب الكاميرا">＋</button><button data-do="zoom-out" title="إبعاد الكاميرا">−</button><button data-do="camera-home" title="إعادة الكاميرا">⌂</button></div><div id="arena-hint"></div></section><aside id="enemy-hud" class="side-hud"></aside></div><footer class="battle-bottom"><div id="hand"></div><div class="turn-controls"><div id="energy-bar"></div>${button('end','إنهاء الدور <span>←</span>','primary end-turn')}<small id="timer-info">Space لإنهاء الدور • Esc للإلغاء</small></div></footer></main>`;
 scene=createBoard('board',state);renderBattle();if(state.phase==='battle'){saveBattle();scheduleAI();}else scheduleAI();resetTimer();}
function runeTutorial(){opts.deckId='preset:human';deckRule='standard';opts.mode='runes';opts.originalRules=true;opts.difficulty='easy';opts.enemy='zombie';opts.race='human';opts.map='plain';startMatch();dialog('تعلّم الرون',`<p>اختر «رون موجو +1» ثم إحدى القاعدتين الزرقاوين بجوار بداية جيشك. الرون ثابت وله 15 صحة؛ تأثيره يبدأ من دورك القادم. يستطيع أي مخلوق مهاجمة رون الخصم من خانة ملاصقة، مهما كانت فئته. الرون المكرر يكلف +2 موجو إضافية لكل نسخة مماثلة نشطة.</p>`,[{text:'ابدأ التدريب',fn:()=>{}}]);}
function configureAbilityLesson(s:GameState){s.starting=0;s.current=0;s.turn=1;s.phase='battle';for(const p of s.players){p.mulligan=true;p.energy=p.maxEnergy;}s.players[0].hand=['R03','S01','NA_human_0005'];const duron=cards.find(c=>c.name==='Duron'&&c.abilityId)!;spawn(s,duron.id,0,{q:s.roundArena?2:1,r:3});const foe=cards.find(c=>c.id==='CM_golem_01')!;spawn(s,foe.id,1,{q:s.roundArena?3:2,r:3});s.events=[];}
function abilityTutorial(){opts.mode='abilities';opts.originalRules=true;opts.deckId='preset:human';deckRule='standard';opts.race='human';opts.enemy='orc';opts.enemyDeck='orc';opts.map='plain';startMatch();selectedUnit=state!.units.find(u=>def(u).name==='Duron')!.uid;renderBattle();dialog('تدريب قدرات الوحوش',`<div class="help-steps"><p><b>١ • حدد الوحش</b>جهزت لك Duron بجوار قائدك، وعدوًا ملاصقًا أمامه.</p><p><b>٢ • استخدم قدرته</b>اضغط زر القدرة الذي يعرض تكلفة 1 موجو من لوحة الوحش، ثم العدو المضيء. هذه التكلفة لا تعيد دفع تكلفة الاستدعاء.</p><p><b>٣ • راقب النتيجة</b>ينقص الموجو وتستهلك القدرة فعل الهجوم لهذا الوحش. يقدر يتحرك بعدها إذا كانت حركته متاحة.</p></div>`,[{text:'جرّب القدرة',fn:()=>{}}]);}
function viewer(){return opts.mode==='local'?state!.current:0;}
function isHumanTurn(){return !!state&&state.winner===undefined&&(opts.mode==='local'||state.current===0)&&!busy;}
function activeTargets(){if(!state||!isHumanTurn())return [];const a=legalActions(state);if(monsterAbility)return a.filter(a=>a.kind==='monsterAbility'&&a.uid===selectedUnit);if(ability)return a.filter(a=>a.kind==='leaderAbility');if(selectedCard!==undefined)return a.filter(a=>a.kind==='playCard'&&a.handIndex===selectedCard);if(selectedUnit!==undefined)return a.filter(a=>(a.kind==='move'||a.kind==='attack'||a.kind==='attackRune'||a.kind==='teleport')&&a.uid===selectedUnit&&(teleport?a.kind==='teleport':a.kind!=='teleport'));return [];}
function mojoIncomeLabel(p:GameState['players'][number]){const m=p.mojoIncome;return m?`توليد الدور: ${m.base} أساس + ${m.runes} رونات + ${m.tiles} خلايا${m.items?` + ${m.items} معدات`:''} = ${m.total}`:'يتولد الموجو في بداية دورك';}
function hud(owner:number){const s=state!,p=s.players[owner],l=leader(s,owner),hero=heroInfo(p.race,!!s.originalRules);return `<div class="compact-hud"><button data-hero="${owner}" class="compact-portrait"><img src="${raceImg(p.race)}" alt="${hero.name}"></button><div><strong>${hero.name}</strong><small>♥ ${Math.max(0,l?.health||0)}/${l?.maxHealth||30}　▤ ${p.hand.length}/${p.deck.length}</small></div><b class="compact-mojo" title="الموجو المتاح • ${mojoIncomeLabel(p)}">${p.energy}</b></div>`;}

const cardText=(c:{id:string,text:string})=>['Z03','O04','O07'].includes(c.id)&&(screen==='battle'?state?.originalRules:opts.originalRules!==false)?'مقاتل':['Z06','Z08'].includes(c.id)&&(screen==='battle'?state?.originalRules:opts.originalRules!==false)?'مقاتل من الموتى':c.id==='W01'&&(screen==='battle'?state?.originalRules:opts.originalRules!==false)?'+1 هجوم • للمحاربين':c.id==='Z05'&&(screen==='battle'?state?.originalRules:opts.originalRules!==false)?'مقاتل من الموتى • نمو الصحة مع موت المخلوقات':c.text;
function abilityDescription(c:typeof cards[number]){const a=abilityFor(c);return a?`<section class="active-ability-box"><span>القدرة النشطة</span><strong>✦ ${a.name} <b>${a.cost} موجو</b></strong><p>${a.description}</p><small>المدى ${a.minRange}–${a.maxRange} • بدل الهجوم الأساسي<br>تكلفة القدرة مستقلة عن تكلفة الاستدعاء.</small></section>`:'';}
function detailBody(id:string){const c=cardById[id]||((id.startsWith('LEADER_')&&state)?def(state.units.find(u=>u.cardId===id)!):undefined);if(!c)return '';const hero=id.startsWith('LEADER_'),isMonster=c.type==='unit'&&!hero,race=raceInfo(c.race),cls=c.type==='unit'?combatClass({cardId:id,isLeader:hero,nativeHero:hero} as Unit):'warrior',frame=hero?'gold':rarityFrame(c),a=hero?abilities[({human:'AT_BLOODLUST',zombie:'AT_DRAWCARD',elf:'AT_HEAL'} as any)[c.race]]:abilityFor(c);return `<div class="physical-inspection"><article class="native-big-card class-${cls}" data-rarity="${cardRarity(c)}"><div class="native-card-art" style="background-image:url('${originalUrl('ready/card-frame-'+frame+'.webp')}')"><img src="${artUrl(id)}" alt="${escapeHTML(c.name)}"><span class="native-card-mojo">${hero?nativeHeroes[c.race].mojo:c.cost}</span><span class="native-card-rarity">${hero?'H':cardRarity(c)}</span><div class="native-printed-stats">${c.type==='unit'?`<b class="stat-red">${c.attack}</b>${c.armor?`<b class="stat-grey">${c.armor}</b>`:''}<b class="stat-green">${c.health}</b>`:''}</div></div><h2>${escapeHTML(c.name)}</h2><div class="native-card-subtitle">${hero?'قائد':isMonster?`${raceNames[c.race]} • ${classNames[cls]}`:({spell:'تعويذة',weapon:'سلاح',armor:'درع',rune:'رون'} as any)[c.type]}</div>${a?`<section class="native-ability-print"><span class="printed-cost">${a.cost}</span><img src="${ui('ability-'+(hero?({human:'AT_BLOODLUST',zombie:'AT_DRAWCARD',elf:'AT_HEAL'} as any)[c.race]:c.abilityId))}" alt=""><div><strong>${a.name}</strong><p>${a.description}</p></div></section>`:`<section class="native-ability-print"><p>${escapeHTML(cardText(c))}</p></section>`}${isMonster&&race?`<section class="native-passive-print"><strong>${race.passiveName}</strong><p>${race.passiveText}</p></section>`:''}</article><div class="native-owner-caption">${hero?'القائد':`${rarityInfo[cardRarity(c)].name} • تملك ${ownedCount(profile,id)} نسخة`}</div></div>`;}

function showCard(id:string){inspectedCard=id;if(screen==='decks'){const count=buildingDeck.filter(x=>x===id).length;dialog(cardById[id].name,detailBody(id)+`<p class="detail-count">${rarityInfo[cardRarity(cardById[id])].name} • تملك ${ownedCount(profile,id)} نسخة • في التشكيلة ${count}</p>`,[{text:'أضف إلى التشكيلة',fn:()=>addToDeck(id)},{text:'إزالة نسخة',fn:()=>{const i=buildingDeck.indexOf(id);if(i>=0)buildingDeck.splice(i,1);renderDeck();}},{text:'إغلاق',fn:()=>{}}]);return;}document.querySelector('#card-detail')?.remove();const el=document.createElement('aside');el.id='card-detail';el.innerHTML=`<button class="detail-close" aria-label="إغلاق تفاصيل البطاقة">×</button>${detailBody(id)}`;el.querySelector('button')!.onclick=()=>el.remove();document.body.append(el);}
function addToDeck(id:string){const n=buildingDeck.filter(x=>x===id).length;if(n>=ownedCount(profile,id)){toast('لا تملك نسخة إضافية من هذه البطاقة. تحصل عليها بالفوز أو من المتجر.');return;}if(buildingDeck.length>=(deckRule==='singleton'?50:200)){toast('المجموعة ممتلئة. أزل بطاقة لإضافة أخرى.');return;}if(n>=(deckRule==='singleton'?1:4)){toast('وصلت للحد الأقصى من هذه البطاقة');return;}buildingDeck.push(id);renderDeck();}
const kindNames:Record<string,string>={sword:'سيف',axe:'فأس',mace:'مطرقة',dagger:'خنجر',spear:'رمح',bow:'قوس',staff:'عصا',artillery:'ذخيرة مدفعية',armour:'خوذة ودرع',shield:'ترس'};
const typeFilters:[string,string][]=[['all','كل الأنواع'],['unit','المقاتلون'],['ability','وحوش بقدرات نشطة'],['spell','التعاويذ'],['weapon','كل الأسلحة'],['sword','⚔ سيوف وفؤوس ومطارق'],['dagger','🗡 خناجر'],['bow','🏹 أقواس'],['staff','🪄 عصي'],['artillery','💣 ذخيرة مدفعية'],['armor','كل الدروع'],['armour','⛑ خوذ ودروع'],['shield','🛡 تروس'],['rune','الرون']];
const melee=['sword','axe','mace','spear'];
function typeMatch(c:Card,f:string){if(f==='all')return true;if(f==='ability')return !!c.abilityId;if(['unit','spell','weapon','armor','rune'].includes(f))return c.type===f;return f==='sword'?melee.includes(c.kind||''):c.kind===f;}
/** Card frame colour follows rarity: common green, uncommon red, rare blue, legendary gold. */
const rarityFrame=(c:Card)=>({C:'archer-green',U:'warrior-red',R:'mage-blue',L:'gold'} as Record<string,string>)[cardRarity(c)]||'gold';
function itemLabel(c:Card){return kindNames[c.kind||'']||(c.type==='weapon'?'سلاح':'درع');}
const statBadge=(k:string,v:string|number,title='')=>`<span class="stat-badge ${k}" title="${title}" style="--badge:url('${originalUrl('ready/badge-'+k+'.webp')}')">${v}</span>`;
const signed=(n:number)=>(n>0?'+':'')+n;
/** Bottom row of a card, like the original: attack bottom-left, health bottom-right, the monster's ability (or the item type) between them. */
function cardStats(c:Card,id:string){if(c.type==='unit'){const a=abilityFor(c),cls=classNames[combatClass({cardId:id,isLeader:false} as Unit)],mid=a?`<img class="ability-badge" src="${ui('ability-'+c.abilityId)}" alt="${a.name}" title="${a.name} • ${a.cost} موجو">`:c.armor?statBadge('armour',c.armor,'درع'):`<span class="speed-stat">${(screen==='battle'?state?.originalRules:opts.originalRules!==false)?cls:(c.range!>1?'◎ '+c.range:'➟ '+c.speed)}</span>`;return `<div class="card-stats badges">${statBadge('attack',c.attack??0,'هجوم')}<span class="stat-mid">${mid}</span>${statBadge('health',c.health??0,'صحة')}</div>`;}
if(c.type==='weapon'||c.type==='armor'){const e=equipOf(id),list=([['attack',e.attack,'هجوم'],['armour',e.armor,'درع'],['health',e.health,'صحة'],['mojo',e.mojo,'موجو كل دور']] as [string,number|undefined,string][]).filter(x=>x[1]).map(([k,v,t])=>statBadge(k,signed(v!),t));const left=list.shift()||'',right=list.length?list.pop()!:'';return `<div class="card-stats badges">${left||'<span></span>'}<span class="stat-mid">${list.join('')}<span class="type-label">${itemLabel(c)}</span></span>${right||'<span></span>'}</div>`;}
return `<div class="card-stats"><span class="type-label">${({spell:'تعويذة',rune:'رون'} as any)[c.type]||''}</span></div>`;}
function cardHTML(id:string,index:number,extra='',count?:number){const c=cardById[id],cost=screen==='battle'&&state?castingCost(state,c,viewer()):c.cost;return `<button draggable="${index>=0}" style="--frame:url('${originalUrl('ready/card-frame-'+rarityFrame(c)+'.webp')}')" data-inspect="${id}" data-rarity="${cardRarity(c)}" class="game-card ${c.race} ${c.rarity==='L'?'legendary':''} ${extra}" ${index>=0?`data-card="${index}"`:''} ${index===-2?`data-add="${id}"`:''} title="${c.name} • ${rarityInfo[cardRarity(c)].name}: ${cardText(c)}"><div class="card-top"><span class="cost-gem">${cost}</span><span class="rarity">${cardRarity(c)}</span></div><div class="card-art"><img src="${artUrl(id)}" alt=""></div><strong class="card-name">${c.name}</strong><small class="card-description">${abilityFor(c)?`✦ ${abilityFor(c).name} • ${abilityFor(c).cost} موجو`:cardText(c)}</small>${cardStats(c,id)}${count!==undefined?`<span class="copy-count">${count} في المجموعة</span>`:''}</button>`;}
function actionStrip(s:GameState,u:Unit){const range=attackRange(s,u),a=abilityFor(u),heroAbility=u.isLeader?abilities[({human:'AT_BLOODLUST',zombie:'AT_DRAWCARD',elf:'AT_HEAL'} as any)[s.players[u.owner].race]]:undefined,special=a||heroAbility,basicId=({warrior:'AT_ATTACK',mage:'AT_BLAST',archer:'AT_SHOOT',artillery:'AT_LOB'} as any)[combatClass(u)],allowed=a?monsterAbilityActions(s,u).length>0:legalActions(s).some(x=>x.kind==='leaderAbility');return `<button data-do="cancel" class="strip-close" title="عودة للبطاقات">▤</button><div class="selected-unit-title"><strong>${def(u).name}</strong><small>⚔ ${effectiveStats(s,u).attack}　♥ ${u.health}　⬟ ${defence(s,u)}</small></div><button data-do="basic-action" class="ability-tile ${!monsterAbility&&!ability?'active':''}"><img src="${ui('ability-'+basicId)}" alt=""><span><strong>هجوم أساسي <b>0</b></strong><small>المدى ${range.min}–${range.max} • اختر عدوًا في المدى</small></span></button>${special?`<button data-do="${a?'monster-ability':'ability'}" class="ability-tile ${monsterAbility||ability?'active':''}" ${!isHumanTurn()||!allowed?'disabled':''}><img src="${ui('ability-'+(a?def(u).abilityId:({human:'AT_BLOODLUST',zombie:'AT_DRAWCARD',elf:'AT_HEAL'} as any)[s.players[u.owner].race]))}" alt=""><span><strong>${special.name} <b>${special.cost}</b></strong><small>${special.description}</small></span></button>`:''}${statusLabels(u).length?`<span class="strip-status">${statusLabels(u).join(' • ')}</span>`:''}`;}
let bannerTurn='';
function turnBanner(){if(!state||state.phase!=='battle'||!isHumanTurn())return;const id=(state.matchId||'')+':'+state.turn+':'+state.current;if(id===bannerTurn)return;bannerTurn=id;document.querySelector('#turn-banner')?.remove();const el=document.createElement('div');el.id='turn-banner';el.textContent=opts.mode==='local'?`دور ${state.current===0?'اللاعب الأول':'اللاعب الثاني'}`:'دورك';document.querySelector('#battle')?.append(el);setTimeout(()=>el.remove(),1500);}
function renderBattle(){if(!state||screen!=='battle')return;turnBanner();const s=state!,owner=viewer(),p=s.players[owner];document.querySelector('#player-hud')!.innerHTML=hud(owner);document.querySelector('#enemy-hud')!.innerHTML=hud(1-owner);document.querySelector('#turn-label')!.innerHTML=`<span class="turn-indicator ${s.current===owner?'your-turn':''}"></span><strong>${s.phase==='mulligan'?'اختيار اليد الأولى':s.winner!==undefined?'انتهت المعركة':s.current===owner?'دورك الآن':'دور الخصم'}</strong><small>الدور ${s.turn}</small>`;document.querySelector('#opponent-hand')!.innerHTML=Array.from({length:s.players[1-owner].hand.length},()=>'<i>✦</i>').join('');
 const hand=document.querySelector('#hand')!;handOffset=Math.max(0,Math.min(handOffset,p.hand.length-8));if(s.phase==='mulligan'){hand.innerHTML=`<div class="mulligan-label"><b>اختر البطاقات لتبديلها</b><small>فرصة واحدة قبل البداية</small>${button('mulligan',mulligan.size?'بدّل '+mulligan.size+' بطاقة':'احتفظ باليد','primary')}</div><div class="cards-row">${p.hand.map((id,i)=>cardHTML(id,i,mulligan.has(i)?'selected':'')).join('')}</div>`;}else hand.innerHTML=`${p.hand.length>8?`<div class="hand-pager">${button('hand-prev','‹')}<span>${handOffset+1}–${Math.min(handOffset+8,p.hand.length)} / ${p.hand.length}</span>${button('hand-next','›')}</div>`:''}<div class="cards-row">${p.hand.slice(handOffset,handOffset+8).map((id,n)=>{const i=n+handOffset;return cardHTML(id,i,`${selectedCard===i?'selected':''} ${castingCost(s,cardById[id],owner)>p.energy||!isHumanTurn()?'unaffordable':''}`);}).join('')}${p.hand.length===0?'<div class="empty-hand">يدك فارغة • اسحب بطاقة مع بداية دورك القادم</div>':''}</div>`;
 const inspector=document.querySelector<HTMLElement>('#unit-inspector')!,unit=s.units.find(u=>u.uid===selectedUnit);inspector.hidden=!unit;if(unit)inspector.innerHTML=actionStrip(s,unit);document.querySelector('#hand')!.classList.toggle('hand-concealed',!!unit);
 document.querySelector('#rune-status')!.textContent=s.originalRules?'◈ الرون: '+activeRunes(s,owner).length+'/'+(s.runeStands||[]).filter(r=>r.owner===owner).length+' • اسحب الرون إلى قاعدة بلونك':'';document.querySelector('#energy-bar')!.innerHTML=`<span>✦</span> <strong>${p.energy}</strong><small> موجو متاح • ${mojoIncomeLabel(p)}</small>`;const end=document.querySelector<HTMLButtonElement>('[data-do="end"]')!;end.disabled=!isHumanTurn()||s.phase==='mulligan'||s.winner!==undefined;end.classList.toggle('ready',s.phase==='battle'&&legalActions(s).length<=1);end.innerHTML=s.current!==owner?'الخصم يفكّر…':s.phase==='mulligan'?'اختر يدك أولًا':'إنهاء الدور <span>←</span>';
 const hint=monsterAbility?'اختر هدف قدرة الوحش من الخانات المضيئة':selectedCard!==undefined?`اختر هدف ${cardById[p.hand[selectedCard]]?.name||'البطاقة'} في الساحة`:ability?'اختر هدف قدرة القائد':selectedUnit!==undefined?'الخانات المضيئة للحركة • الأحمر للهجوم':opts.mode==='tutorial'?'استدعِ مقاتلًا حول القائد، ثم أنهِ الدور ليستطيع التحرك.':(matchMedia('(pointer: coarse)').matches?'اسحب بإصبع لتحريك الكاميرا • قرّب وبعّد بإصبعين • ⌂ يعرض الساحة كاملة':'اسحب بالزر الأيمن لتحريك الكاميرا • عجلة الماوس للتقريب');document.querySelector('#arena-hint')!.textContent=hint;scene?.setView({state:s,owner:viewer(),selected:selectedUnit,targets:activeTargets(),onClick:clickHex,onHover:hoverHex});hoverHex(scene?.hover);}
function clearSelection(){selectedUnit=selectedCard=undefined;monsterAbility=false;ability=false;teleport=false;renderBattle();}
function clickHex(h:Hex){if(modalOpen||!isHumanTurn()||!state||state.phase!=='battle')return;const u=occupant(state,h),stand=runeAt(state,h),targets=activeTargets();if(u&&selectedCard===undefined&&!ability&&!monsterAbility&&!targets.some(a=>a.kind==='attack'&&a.targetUid===u.uid))showCard(u.cardId);let a=targets.find(a=>(a.kind==='move'||a.kind==='teleport')&&key(a.to)===key(h)||(a.kind==='playCard'||a.kind==='leaderAbility'||a.kind==='monsterAbility')&&a.target&&key(a.target)===key(h)||a.kind==='attack'&&u?.uid===a.targetUid||a.kind==='attackRune'&&stand?.id===a.standId);if(a){act(a);return;}if(u?.owner===state.current){selectedUnit=u.uid;selectedCard=undefined;monsterAbility=false;ability=false;teleport=false;sound();renderBattle();}else if(selectedCard!==undefined||ability||monsterAbility)toast('هذا الهدف غير مسموح. اختر إحدى الخانات المضيئة.');else clearSelection();}
function hoverHex(h?:Hex){const el=document.querySelector<HTMLDivElement>('#hover-info');if(!el||!state)return;if(!h){el.hidden=true;return;}const u=occupant(state,h),stand=runeAt(state,h),tile=state.tiles[key(h)],token=state.tokens[key(h)];if(stand){el.innerHTML=`<strong>${stand.cardId?cardById[stand.cardId].name:'قاعدة رون فارغة'} • ${stand.owner===viewer()?'لك':'للخصم'}</strong><span>${stand.cardId?'♥ '+stand.health+'/'+stand.maxHealth:'اسحب بطاقة رون إلى هذه القاعدة'}</span><small>${stand.cardId?cardById[stand.cardId].text:'لك قاعدتان. يمكن استبدال رون قديم بآخر.'}</small>`;}else if(u){const st=effectiveStats(state,u);const chosen=state.units.find(v=>v.uid===selectedUnit);const forecast=chosen&&activeTargets().some(a=>a.kind==='attack'&&a.targetUid===u.uid)?damagePreview(state,chosen,u):undefined;el.innerHTML=`<strong>${def(u).name}</strong><span>⚔ ${st.attack}　♥ ${u.health}/${u.maxHealth}　⬟ ${defence(state,u)}/${st.armor}　◎ ${attackRange(state,u).min}–${attackRange(state,u).max}</span><small>${cardText(def(u))}${abilityFor(u)?' • ✦ '+abilityFor(u).name+' ('+abilityFor(u).cost+' موجو)':''}${statusLabels(u).length?' • '+statusLabels(u).join(' / '):''}${u.poisoned?' • مسموم':''}${u.shielded?' • درع سحري':''}${u.summoned?' • دوار الاستدعاء':''}</small>${cellBonuses(state,h).length?`<small class="cell-bonus-info">الخانة: ${cellBonuses(state,h).map(b=>`+${b.amount} ${b.label}${b.kind==='mojo'?' في بداية دورك القادم':' أثناء الوقوف'}`).join(' • ')}</small>`:''}${forecast?`<b class="forecast">الضرر: ${forecast.dealt} • الرد المتوقع: ${forecast.counter}</b>`:''}`;}else if(tile||token){el.innerHTML=`<strong>${({rock:'بلورة صخرية',altar:'مذبح الطاقة',tower:'برج الحراسة',spring:'ينبوع الحياة',swamp:'مستنقع',star:'نجمة القوة',shield:'رمز الحماية',heart:'رمز الحياة'} as any)[tile||token]}</strong><small>${({rock:'تمنع الوقوف وتحجب الرماية.',altar:state.originalRules?'+2 موجو في بداية الدور عند الوقوف.':'+1 طاقة بداية الدور إذا وقفت وحدتك هنا.',tower:'+1 درع، و+1 مدى للرماة.',spring:'يعالج وحدتك 2 صحة في بداية دورها.',swamp:'دخوله ينهي الحركة، إلا للطائر.',star:state.originalRules?'+2 هجوم طوال الوقوف على الرمز.':'+1 هجوم دائم لأول مقاتل يلتقطه.',shield:state.originalRules?'+2 دفاع طوال الوقوف على الرمز.':'+1 درع دائم لأول مقاتل يلتقطه.',heart:state.originalRules?'+2 صحة وإزالة السم في بداية الدور؛ قد تتجاوز الصحة الأصلية.':'+2 صحة دائمة لأول مقاتل يلتقطه.'} as any)[tile||token]}</small>`;}else {el.hidden=true;return;}el.hidden=false;}
function act(a:Action){if(!state)return;const old=state,next=applyAction(state,a);if(next===state)return;if((a.kind==='move'||a.kind==='teleport'||a.kind==='playCard'&&cardById[old.players[old.current].hand[a.handIndex]].type!=='spell')&&opts.mode!=='local')history.push(structuredClone(state));else if(a.kind!=='mulligan')history=[];state=next;selectedCard=undefined;monsterAbility=false;ability=false;if(a.kind==='move'||a.kind==='attack'||a.kind==='attackRune'||a.kind==='monsterAbility'){selectedUnit=next.units.some(u=>u.uid===(a as any).uid)?(a as any).uid:undefined;}else selectedUnit=undefined;teleport=false;mulligan.clear();sound(a.kind==='attack'||a.kind==='attackRune'||a.kind==='monsterAbility'?'attack':a.kind==='playCard'?'summon':'click');renderBattle();scene?.effects(next.events,old);if(old.current===1&&opts.mode!=='local'){const card=next.events.find(e=>e.kind==='card');if(card?.text){document.querySelector('#enemy-card-play')?.remove();const shown=document.createElement('div');shown.id='enemy-card-play';shown.innerHTML='<span>'+ (cardById[card.text].type==='unit'?'الخصم يستدعي':'الخصم يستخدم')+'</span>'+cardHTML(card.text,-1);document.body.append(shown);setTimeout(()=>shown.remove(),2000);}}saveBattle();if(next.winner!==undefined){finished();return;}if(a.kind==='endTurn'||old.phase!==next.phase){resetTimer();showTurn();if(opts.mode==='local'){document.querySelector('#hand')!.innerHTML='<div class="empty-hand">سلّم الجهاز للاعب التالي</div>';dialog('سلّم الجهاز للاعب التالي',`<p>الدور الآن لقائد ${leaders[next.players[next.current].race].name}. اضغط عندما يكون اللاعب جاهزًا.</p>`,[{text:'أنا جاهز',fn:()=>{renderBattle();resetTimer();}}]);}}if(a.kind==='mulligan'&&next.phase==='mulligan'&&opts.mode==='local'){document.querySelector('#hand')!.innerHTML='<div class="empty-hand">اختر يد اللاعب التالي</div>';dialog('اختيار يد اللاعب الثاني','<p>سلّم الجهاز للاعب الثاني ليختار بطاقاته.</p>',[{text:'أنا جاهز',fn:renderBattle}]);}scheduleAI();}
function saveBattle(){if(state?.winner===undefined)store.set('battle',{state,opts});else store.set('battle',null);}
function scheduleAI(){clearTimeout(aiTimer);if(!state||state.winner!==undefined||opts.mode==='local'||state.current!==1)return;const id=runId;aiTimer=setTimeout(()=>{if(id!==runId||!state||screen!=='battle')return;if(modalOpen){scheduleAI();return;}if(state.phase==='mulligan'){act({kind:'mulligan',indexes:state.players[1].hand.flatMap((id,i)=>cardById[id].cost>4?[i]:[])});return;}const a=chooseAI(state,opts.difficulty);act(a);},settings.speed);}
function showTurn(){const old=document.querySelector('#turn-banner');old?.remove();const el=document.createElement('div');el.id='turn-banner';el.innerHTML=`<img src="${raceImg(state!.players[state!.current].race)}"><span>${state!.current===viewer()?'دورك':'دور الخصم'}</span>`;document.body.append(el);setTimeout(()=>el.remove(),1300);}
function resetTimer(){clearInterval(timer);seconds=60;if(!settings.timer||state?.phase!=='battle')return;timer=setInterval(()=>{if(modalOpen||screen!=='battle'||!state||state.winner!==undefined)return;seconds--;const el=document.querySelector('#timer-info');if(el)el.textContent=`الوقت المتبقي: ${seconds} ثانية`;if(seconds<=0)act({kind:'endTurn'});},1000);}
function endTurn(){if(!isHumanTurn()||!state||state.phase!=='battle')return;const remain=legalActions(state).length>1;if(remain)dialog('إنهاء دورك؟','<p>ما زالت لديك أفعال متاحة. هل تريد تمرير الدور للخصم؟</p>',[{text:'إنهاء الدور',fn:()=>act({kind:'endTurn'})},{text:'أكمل دوري',fn:()=>{}}]);else act({kind:'endTurn'});}
function finished(){clearTimeout(aiTimer);clearInterval(timer);const match=state!,won=match.winner===0;const outcome=grantVictory(profile,match.matchId||'',opts.rewardEligible,won);let reward:Reward|undefined;try{if(outcome.reward&&!outcome.alreadyClaimed)persistProfile(outcome.profile);reward=outcome.reward;}catch{toast('تعذر حفظ مكافأة الفوز');}let dailyBonus=0;if(opts.mode==='daily'&&won&&store.get('daily-claimed','')!==todayKey()){try{persistProfile(grantChest({...profile,coins:profile.coins+DAILY_COINS},'mystery'));store.set('daily-claimed',todayKey());dailyBonus=DAILY_COINS;}catch{}}let questLine='';if(match.quest){questId=match.quest.id;if(won){try{const g=grantQuestRoom(profile,match.quest.id,match.quest.room);if(g.prize){persistProfile(g.profile);const q=questById[match.quest.id],next=QUESTS[QUESTS.indexOf(q)+1];questLine=`<div class="quest-prize"><h3>جائزة المهمة</h3><div class="reward-coins"><img src="${ui('coin')}" alt="عملة"> +${g.prize.coins}</div>${g.prize.chest?`<img class="prize-chest" src="${ui('chest-'+g.prize.chest)}" alt=""><p>${CHESTS[g.prize.chest].name} من الزعيم! تفتحه من «صناديقي».</p>`:''}${questComplete(profile,q)?`<p class="quest-done">أكملت ${q.title}!${next?` فتحت ${next.title}.`:''}</p>`:''}</div>`;}else questLine='<p class="quest-done">فزت بهذه الغرفة من قبل، جائزة المهمة تُعطى أول مرة فقط.</p>';}catch{toast('تعذر حفظ جائزة المهمة');}}}const result=match.winner==='draw'?'تعادل':won?'انتصار!':'انتهت المعركة';setTimeout(()=>dialog(result,`<img class="result-logo" src="${ui(match.winner===0||opts.mode==='local'&&match.winner!=='draw'?'winner':'badluck')}" alt="${result}">${questLine}${dailyBonus?`<p class="daily-bonus">جائزة تحدي اليوم: +${dailyBonus} عملة + صندوق غامض</p><img class="prize-chest" src="${ui('chest-mystery')}" alt="">`:''}<div class="victory-content"><img class="winner-hero" src="${raceImg(match.players[match.winner==='draw'?0:match.winner!].race)}" alt=""><div>${reward?`<h3>غنائم الانتصار</h3><div class="reward-coins"><img src="${ui('coin')}" alt="عملة"> +${reward.coins}</div><p>${reward.newCard?'بطاقة جديدة!':'نسخة إضافية لمجموعتك'}</p>${cardHTML(reward.cardId,-3)}<strong class="reward-rarity">${rarityInfo[reward.rarity].name} • تملك ${ownedCount(profile,reward.cardId)} نسخة</strong><small>حُفظت المكافأة تلقائيًا • رصيدك ${profile.coins} عملة</small>`:`<p>${won?'أحسنت قيادة جيشك.':'جرّب تشكيلة وتمركزًا آخر.'}</p><small>${opts.rewardEligible?'المكافآت عند الفوز ضد الكمبيوتر.':'التدريب واللعب المحلي والمعارك القديمة بلا مكافآت.'}</small>`}</div></div>`,[...(match.quest?[{text:'خريطة المهمة',fn:()=>questMap(match.quest!.id)}]:[]),{text:'العودة إلى الكتاب',fn:menu},{text:'مجموعتي',fn:()=>deckBuilder()},{text:'عرض الساحة',fn:()=>{}}]),700);}

function dialog(title:string,body:string,actions:{text:string,fn:()=>void}[]){document.querySelector('#dialog')?.remove();modalOpen=true;const el=document.createElement('div');el.id='dialog';el.innerHTML=`<div class="dialog-box" role="dialog" aria-modal="true" aria-label="${title}"><h2>${title}</h2><div class="dialog-body">${body}</div><div class="dialog-buttons">${actions.map((a,i)=>`<button class="${i===0?'primary':''}" data-dialog="${i}">${a.text}</button>`).join('')}</div></div>`;document.body.append(el);el.querySelectorAll<HTMLButtonElement>('[data-dialog]').forEach(b=>b.onclick=()=>{el.remove();modalOpen=false;actions[+b.dataset.dialog!].fn();});}
function help(){dialog('قواعد اللعبة • مراجعة الملفات الأصلية',`<div class="help-steps"><p><b>الاستدعاء</b>من اليد إلى خانة فارغة ملاصقة لقائدك الحالي فقط؛ اللاعب والكمبيوتر لهما نفس القيود. أُزيل الإحياء البعيد التجريبي من القواعد الأصلية. رون الانطلاق يسمح بحركة الوحش الجديد بعد استدعائه، ولا يسمح باستدعاء بعيد.</p><p><b>الرون</b>أربع قواعد في الساحة: اثنتان لكل طرف. اختر بطاقة رون ثم قاعدة بلونك. له 15 صحة ويمكن مهاجمته من خانة ملاصقة بأي فئة، حتى الرامي والمدفعية. تستطيع استبداله؛ تكلف النسخة المماثلة +2 موجو لكل نسخة نشطة. هناك سبعة رونات مستعادة بتكلفتها وتأثيرها الأصليين.</p><p><b>الحركة والقتال</b>الهجوم الأساسي مجاني، ولا توجد ضربة رد تلقائية عامة. تستطيع تنفيذ الحركة غير المستهلكة بعد الهجوم. المحارب غير القائد يتحرك مرتين إذا تنازل عن الهجوم؛ المدفعية تختار الحركة أو الهجوم. الجديد يهاجم فورًا وينتظر للحركة، إلا مع رون الانطلاق.</p><p><b>المدى والدفاع</b>المحارب 1، الساحر 1–2، الرامي 2–3، المدفعية 3 فقط. الدفاع يمتص الضرر وينقص ثم يتجدد في دورك. السلاح يطابق الفئة؛ يمكن الجمع بين ترس ودرع بدن.</p><p><b>القادة والموارد</b>القادة الأربعة يستخدمون إحصاءات وموجو وقدرات مستعادة من الأصل. الموجو يتجدد حسب القائد والرون والخانات. البطاقات ست في البداية ولا يسحب صاحب البداية في أول دور. اليد تقبل حتى 200 بطاقة؛ استخدم أسهم تصفح اليد إذا كثرت.</p><p><b>قدرات الوحوش</b>حدد وحشًا في الساحة، ثم اضغط زر قدرته الذي يعرض تكلفة الموجو. الخانات المضيئة تحدد أهدافها ومدىها. القدرة بدل الهجوم الأساسي، حتى لو كانت مجانية أو علاجًا. يستطيع المستدعى حديثًا استخدامها. التكلفة منفصلة عن استدعاء البطاقة.</p><p><b>الأعراق</b>البشر +1 قوة لكل صديق مجاور، الأورك +1 لكل أورك آخر دون حد +3 القديم، الموتى +1 صحة عند موت مخلوق، الجان +4 صحة عند نقاء الوحوش من الأعراق الأخرى.</p><p><b>المجموعات والنهاية</b>العادي 30–200 بطاقة وأربع نسخ كحد أعلى، مع خلط الأعراق. توجد أيضًا قواعد الفريد والقبلي والبسيط والحشود. عند نفاد المجموعة يبدأ أرماغيدون: ضرر متزايد لجميع مخلوقات صاحبها في كل دور.</p><p><b>حدود الاستعادة</b>جداول اللعبة الأصلية استُعيدت، لكن تتوفر الأعراق الأصلية الستة عشر وميزاتها، مع بطاقات أصلية مختارة، منها 92 وحشًا يمتلك قدرات نشطة وتكاليف موجو مستعادة. المجموعة التجريبية محفوظة للتوافق. استُعيدت القدرات النشطة الـ53 الموجودة في جدول الوحوش، مع بقاء كتالوج البطاقات الكامل والتعاويذ الأصلية غير مكتملين.</p></div>`,[{text:'تدريب الرون',fn:runeTutorial},{text:'فهمت',fn:()=>{}}]);}
function settingsDialog(){dialog('الإعدادات',`<div class="settings-form"><label><input id="set-sound" type="checkbox" ${settings.sound?'checked':''}> مؤثرات صوتية</label><label><input id="set-timer" type="checkbox" ${settings.timer?'checked':''}> مؤقت 60 ثانية للدور</label><label>سرعة حركات الخصم<select id="set-speed"><option value="1000" ${settings.speed===1000?'selected':''}>هادئة</option><option value="650" ${settings.speed===650?'selected':''}>عادية</option><option value="250" ${settings.speed===250?'selected':''}>سريعة</option></select></label></div>`,[{text:'حفظ',fn:()=>{settings.sound=!!(document.querySelector('#set-sound') as HTMLInputElement)?.checked;/* captured below before removal */}}]);const dlg=document.querySelector('#dialog')!;const save=dlg.querySelector<HTMLButtonElement>('[data-dialog="0"]')!;save.onclick=()=>{settings={sound:(dlg.querySelector('#set-sound') as HTMLInputElement).checked,timer:(dlg.querySelector('#set-timer') as HTMLInputElement).checked,speed:+(dlg.querySelector('#set-speed') as HTMLSelectElement).value};store.set('settings',settings);dlg.remove();modalOpen=false;resetTimer();toast('تم حفظ الإعدادات');};}
function deckBuilder(race=buildingRace,from='menu',entry?:SavedDeck){cleanup();screen='decks';buildingRace=race;builderReturn=from;buildingId=entry?.id||'';buildingName=entry?.name||'تشكيلتي الجديدة';if(entry)deckRule=entry.rule;buildingDeck=entry?[...entry.cards]:[...profile.starterDeck];filterRace='all';filterType='all';filterCost='all';renderDeck();}
function renderDeck(){const error=playableError(profile,buildingDeck,opts.race,deckRule),counts:Record<string,number>={};for(const id of buildingDeck)if(cardById[id])counts[id]=(counts[id]||0)+1;app.innerHTML=`<main class="page deck-page"><header class="page-header">${button('deck-back','← '+(builderReturn==='setup'?'تجهيز المعركة':'الرئيسية'),'back')}<div><div class="eyebrow">بطاقاتك المملوكة • اربح أو اشترِ لتوسعة مجموعتك</div><h2>ابنِ تشكيلتك</h2></div><label>مجموعة محفوظة<select id="saved-deck"><option value="">تشكيلة جديدة</option>${savedDecks.map(d=>`<option value="${d.id}" ${buildingId===d.id?'selected':''}>${escapeHTML(d.name)}</option>`).join('')}</select></label></header><div class="deck-layout"><section class="collection"><div class="collection-filters"><select id="catalog-mode"><option value="owned" ${catalogMode==='owned'?'selected':''}>المملوكة فقط</option><option value="all" ${catalogMode==='all'?'selected':''}>كل البطاقات • معاينة</option></select><select id="filter-rarity"><option value="all">كل الندرات</option>${rarityOrder.map(r=>`<option value="${r}" ${filterRarity===r?'selected':''}>${rarityInfo[r].name}</option>`).join('')}</select><select id="deck-rule">${([['standard','العادي: 30–200 / أربع نسخ'],['singleton','الفريد: 50 مختلفة'],['tribal','القبلي: عرق واحد / 60% وحوش'],['pauper','البسيط: عادي وغير شائع'],['hordes','الحشود: وحوش فقط']] as const).map(([v,n])=>`<option value="${v}" ${deckRule===v?'selected':''}>${n}</option>`).join('')}</select><select id="filter-race"><option value="all">كل الأعراق</option>${[...monsterRaces,'neutral'].map(r=>`<option value="${r}" ${r===filterRace?'selected':''}>${raceNames[r]}</option>`).join('')}</select><select id="filter-type">${typeFilters.map(([v,n])=>`<option value="${v}" ${v===filterType?'selected':''}>${n}</option>`).join('')}</select><select id="filter-cost"><option value="all">كل التكاليف</option>${Array.from(new Set(cards.map(c=>c.cost))).sort((a,b)=>a-b).map(c=>`<option ${filterCost===String(c)?'selected':''} value="${c}">${c} موجو</option>`).join('')}</select></div>${filterRace!=='all'&&raceInfo(filterRace)?`<div class="collection-race-info"><strong>${raceNames[filterRace]} • ${raceInfo(filterRace).passiveName}</strong><p>${raceInfo(filterRace).passiveText}</p></div>`:''}<div class="collection-grid">${(()=>{const list=cards.filter(c=>(catalogMode==='all'||ownedCount(profile,c.id)>0)&&(filterRarity==='all'||cardRarity(c)===filterRarity)&&(filterRace==='all'||c.race===filterRace)&&typeMatch(c,filterType)&&(filterCost==='all'||c.cost===+filterCost));const key=[catalogMode,filterRarity,filterRace,filterType,filterCost].join('|');if(key!==collectionKey){collectionKey=key;collectionLimit=COLLECTION_PAGE;}return list.slice(0,collectionLimit).map(c=>cardHTML(c.id,-2,ownedCount(profile,c.id)?'':'locked-card',counts[c.id]||0)).join('')+(list.length>collectionLimit?button('more-cards',`عرض المزيد • ${list.length-collectionLimit} بطاقة متبقية`,'more-cards'):'');})()}</div></section><aside class="deck-list"><label class="deck-name-label">اسم التشكيلة<input id="deck-name" maxlength="50" value="${escapeHTML(buildingName)}"></label><div class="deck-list-title"><h3>بطاقات التشكيلة</h3><strong class="${!error?'complete':''}">${buildingDeck.length}<small> / ${deckRule==='singleton'?50:200}</small></strong></div><div class="deck-race-summary">${deckSummary(buildingDeck)}</div><div class="deck-entries">${Object.entries(counts).sort((a,b)=>cardById[a[0]].cost-cardById[b[0]].cost).map(([id,n])=>`<div class="deck-entry-row"><button data-inspect="${id}" title="تفاصيل البطاقة"><span class="mini-cost">${cardById[id].cost}</span><img src="${artUrl(id)}" alt=""><strong>${cardById[id].name}</strong><span>×${n}<small> / ${ownedCount(profile,id)}</small></span></button><button data-remove="${id}" aria-label="إزالة نسخة من ${escapeHTML(cardById[id].name)}">−</button></div>`).join('')}</div><p class="validation ${error?'invalid':''}">${error||'✓ المجموعة مطابقة للقواعد'}</p><button data-do="save-deck" class="primary" ${error?'disabled':''}>حفظ واختيار التشكيلة</button><label class="preset-select">تشكيلة جاهزة من عرق<select id="preset-race">${monsterRaces.map(r=>`<option value="${r}" ${buildingRace===r?'selected':''}>${raceNames[r]}</option>`).join('')}</select></label><div class="deck-secondary">${button('reset-deck','استخدم مجموعة البداية')}${button('clear-deck','إفراغ')}</div><small>اضغط أي بطاقة لقراءة اسمها وعرقها وميزته، ثم اختر الإضافة.</small></aside></div></main>`;}
app.addEventListener('click',e=>{const b=(e.target as HTMLElement).closest<HTMLButtonElement>('button');if(!b||b.disabled)return;if(b.dataset.hero){if(state&&state.phase==='battle'&&+b.dataset.hero===viewer()){selectedUnit=leader(state,viewer())?.uid;selectedCard=undefined;monsterAbility=ability=false;renderBattle();}return;}if(b.dataset.starter){try{persistProfile(chooseStarter(profile,b.dataset.starter));opts.deckId='starter';store.set('selected-deck','starter');menu();}catch(err){toast(String(err));}return;}if(b.dataset.buy){buy(b.dataset.buy);return;}if(b.dataset.race){opts.race=b.dataset.race;screen==='quest-map'?questMap():setup(opts.mode);return;}if(b.dataset.quest){questMap(b.dataset.quest);return;}if(b.dataset.openChest){openChestUI(b.dataset.openChest as ChestType);return;}if(b.dataset.buyChest){const r=buyChest(profile,b.dataset.buyChest as ChestType);if(r.error){toast(r.error);return;}try{persistProfile(r.profile);}catch{toast('تعذر حفظ الشراء');return;}toast('اشتريت '+CHESTS[b.dataset.buyChest as ChestType].name);chests();return;}if(b.dataset.room){roomDialog(+b.dataset.room);return;}if(b.dataset.map){opts.map=b.dataset.map;setup(opts.mode);return;}if(b.dataset.stage){opts.stage=+b.dataset.stage;opts.mode='campaign';opts.enemy=races[(opts.stage+1)%4];opts.map=maps[opts.stage%3].id;opts.difficulty=['normal','normal','hard','hard','expert'][opts.stage];startMatch();return;}if(b.dataset.add){showCard(b.dataset.add);return;}if(b.dataset.remove){buildingDeck.splice(buildingDeck.indexOf(b.dataset.remove),1);renderDeck();return;}if(b.dataset.card!==undefined){const i=+b.dataset.card;showCard(state!.players[viewer()].hand[i]);if(!isHumanTurn())return;if(state!.phase==='mulligan'){mulligan.has(i)?mulligan.delete(i):mulligan.add(i);renderBattle();return;}const id=state!.players[viewer()].hand[i],c=cardById[id];if(castingCost(state!,c,viewer())>state!.players[viewer()].energy){toast('الطاقة لا تكفي لهذه البطاقة');return;}selectedUnit=undefined;selectedCard=selectedCard===i?undefined:i;monsterAbility=false;ability=false;const targets=activeTargets();const immediate=targets.find(a=>a.kind==='playCard'&&!a.target);if(immediate){act(immediate);return;}if(selectedCard!==undefined&&!targets.length){toast(c.type==='unit'?'لا توجد خانة استدعاء فارغة حول قائدك.':'لا يوجد هدف صالح لهذه البطاقة الآن.');selectedCard=undefined;}sound();renderBattle();return;}
 if(b.dataset.inspect){showCard(b.dataset.inspect);return;}
 switch(b.dataset.do){case'menu':menu();break;case'shop':shop();break;case'quests':quests();break;case'chests':chests();break;case'quest-back':questMap();break;case'setup':setup();break;case'daily':dailyChallenge();break;case'passplay':setup('local');break;case'campaign':campaign();break;case'tutorial':tutorial();break;case'runes-tutorial':runeTutorial();break;case'ability-tutorial':abilityTutorial();break;case'hand-prev':handOffset=Math.max(0,handOffset-8);selectedCard=undefined;renderBattle();break;case'hand-next':handOffset+=8;selectedCard=undefined;renderBattle();break;case'decks':deckBuilder();break;case'start':{const d=chosenDeck(),error=playableError(profile,d.cards,opts.race,opts.originalRules===false?'legacy':d.rule);if(error){toast(error);break;}startMatch();break;}case'edit-match-deck':{const d=chosenDeck();deckBuilder(cardById[d.cards.find(id=>cardById[id]?.type==='unit')||'']?.race||opts.race,'setup',savedDecks.find(x=>x.id===d.id)||{...d,id:''});break;}case'new-match-deck':deckBuilder(opts.race,'setup',{id:'',name:'تشكيلتي الجديدة',hero:opts.race,cards:[],rule:'standard'});break;case'more-shop':{const y=scrollY,grid=document.querySelector('.shop-grid'),top=grid?.scrollTop||0;shopLimit+=COLLECTION_PAGE;shop();const again=document.querySelector('.shop-grid');if(again)again.scrollTop=top;scrollTo(0,y);break;}case'more-cards':{const grid=document.querySelector('.collection'),top=grid?.scrollTop||0,y=scrollY;collectionLimit+=COLLECTION_PAGE;renderDeck();const again=document.querySelector('.collection');if(again)again.scrollTop=top;scrollTo(0,y);break;}case'deck-back':builderReturn==='setup'?setup(opts.mode):menu();break;case'continue':{const save=store.get<any>('battle',null);if(save)startMatch(save);break;}case'help':help();break;case'settings':settingsDialog();break;case'cancel':clearSelection();break;case'teleport':teleport=!teleport;renderBattle();break;case'zoom-in':scene?.zoomBy(1.12);break;case'zoom-out':scene?.zoomBy(.89);break;case'camera-home':scene?.resetCamera();break;case'end':endTurn();break;case'mulligan':if(isHumanTurn())act({kind:'mulligan',indexes:[...mulligan]});break;case'basic-action':monsterAbility=false;ability=false;renderBattle();break;case'monster-ability':{const u=state?.units.find(u=>u.uid===selectedUnit);if(!u||!isHumanTurn())break;selectedCard=undefined;ability=false;monsterAbility=!monsterAbility;const acts=activeTargets(),immediate=acts.find(a=>a.kind==='monsterAbility'&&!a.target);if(monsterAbility&&immediate)act(immediate);else renderBattle();break;}case'ability':monsterAbility=false;if(isHumanTurn()){selectedUnit=selectedCard=undefined;ability=!ability;const targets=activeTargets();const immediate=targets.find(a=>a.kind==='leaderAbility'&&!a.target);if(immediate)act(immediate);else if(!targets.length){ability=false;toast('لا يوجد هدف صالح للقدرة');}renderBattle();}break;case'log':dialog('سجل المعركة',`<div class="battle-log">${state!.log.slice().reverse().map(t=>`<p>${t}</p>`).join('')}</div>`,[{text:'عودة للمعركة',fn:()=>{}}]);break;case'sound':settings.sound=!settings.sound;store.set('settings',settings);b.textContent=settings.sound?'♫':'♩';break;case'pause':{const press=(d:string)=>()=>setTimeout(()=>document.querySelector<HTMLElement>(`#battle [data-do="${d}"]`)?.click(),0);dialog('خيارات التوقف',`<p>تُحفظ المباراة تلقائيًا. يمكنك العودة لها من القائمة الرئيسية على هذا المتصفح.</p>`,[{text:'أكمل المعركة',fn:()=>{}},{text:'سجل المعركة',fn:press('log')},{text:'قواعد اللعبة',fn:press('help')},{text:settings.sound?'كتم الصوت':'تشغيل الصوت',fn:press('sound')},{text:'الإعدادات',fn:settingsDialog},{text:'القائمة الرئيسية',fn:menu}]);break;}case'save-deck':{if(playableError(profile,buildingDeck,opts.race,deckRule))break;const d:SavedDeck={id:buildingId||'deck-'+Date.now(),name:buildingName.trim()||'تشكيلتي',hero:opts.race,cards:[...buildingDeck],rule:deckRule};savedDecks=[...savedDecks.filter(x=>x.id!==d.id),d];store.set('saved-decks',savedDecks);opts.deckId=d.id;store.set('selected-deck',d.id);buildingId=d.id;toast('تم حفظ واختيار تشكيلتك');builderReturn==='setup'?setup(opts.mode):renderDeck();break;}case'reset-deck':buildingDeck=[...profile.starterDeck];renderDeck();break;case'clear-deck':buildingDeck=[];renderDeck();break;}});
app.addEventListener('change',e=>{const el=e.target as HTMLSelectElement;switch(el.id){case'shop-rarity':shopRarity=el.value;shop();break;case'shop-race':shopRace=el.value;shop();break;case'shop-type':shopType=el.value;shop();break;case'filter-rarity':filterRarity=el.value;renderDeck();break;case'catalog-mode':catalogMode=el.value;renderDeck();break;case'rules':opts.originalRules=el.value==='source';setup(opts.mode);break;case'enemy':opts.enemy=el.value;break;case'enemy-deck':opts.enemyDeck=el.value;break;case'difficulty':opts.difficulty=el.value;store.set('difficulty',el.value);break;case'mode':opts.mode=el.value;setup(opts.mode);break;case'saved-deck':{const d=savedDecks.find(d=>d.id===el.value);deckBuilder(opts.race,builderReturn,d);break;}case'preset-race':buildingRace=el.value;break;case'match-deck':opts.deckId=el.value;store.set('selected-deck',el.value);if(savedDecks.find(d=>d.id===el.value))deckRule=savedDecks.find(d=>d.id===el.value)!.rule;screen==='quest-map'?questMap():setup(opts.mode);break;case'deck-rule':deckRule=el.value as DeckRule;store.set('deck-rule',deckRule);renderDeck();break;case'filter-race':filterRace=el.value;renderDeck();break;case'filter-type':filterType=el.value;renderDeck();break;case'filter-cost':filterCost=el.value;renderDeck();break;}});
document.addEventListener('keydown',e=>{if(screen!=='battle'||modalOpen||(e.target as HTMLElement).tagName==='SELECT')return;if(e.key==='Escape'){if(selectedUnit===undefined&&selectedCard===undefined)document.querySelector<HTMLElement>('#battle .gear-button')?.click();else clearSelection();}if(e.code==='Space'){e.preventDefault();endTurn();}if(e.ctrlKey&&e.key==='z'&&isHumanTurn()&&history.length){e.preventDefault();state=history.pop();clearSelection();saveBattle();toast('تم التراجع عن آخر حركة');}});
document.addEventListener('contextmenu',e=>{if(screen==='battle'){e.preventDefault();clearSelection();}});
app.addEventListener('dragstart',e=>{const b=(e.target as HTMLElement).closest<HTMLElement>('[data-card]');if(!b||!isHumanTurn()||state?.phase!=='battle'){e.preventDefault();return;}const i=+b.dataset.card!;if(castingCost(state,cardById[state.players[viewer()].hand[i]],viewer())>state.players[viewer()].energy){e.preventDefault();return;}selectedCard=i;selectedUnit=undefined;monsterAbility=false;ability=false;e.dataTransfer?.setData('text/plain',String(i));scene?.setView({state,owner:viewer(),targets:activeTargets(),onClick:clickHex,onHover:hoverHex});});
app.addEventListener('dragover',e=>{if((e.target as HTMLElement).closest('#board'))e.preventDefault();});
app.addEventListener('drop',e=>{if(!scene||!state)return;const canvas=document.querySelector('#board canvas');if(!canvas)return;const r=canvas.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)return;e.preventDefault();const h=scene.hexAt((e.clientX-r.left)/r.width*1120,(e.clientY-r.top)/r.height*650);if(h)clickHex(h);});
app.addEventListener('input',e=>{const input=e.target as HTMLInputElement;if(input.id==='deck-name')buildingName=input.value;});
document.addEventListener('click',e=>{const b=(e.target as HTMLElement).closest<HTMLElement>('#enemy-card-play [data-inspect]');if(b)showCard(b.dataset.inspect!);});
menu();

import './v7.css';

// Development-only fixture: runs real legal AI actions, then exercises the production reward/result path.
if((import.meta as any).env.DEV&&location.hash==='#qa-reward'){dialog('اختبار مكافأة الفوز','<p>مناوشة اختبارية آلية بقائد خصم ذي صحة واحدة ومجموعة فارغة. لا تظهر هذه الأداة في النسخة المنشورة.</p>',[{text:'تشغيل اختبار المكافأة',fn:()=>{let demo=newGame(17,profile.starterDeck,'human',formatStarterDeck('orc','standard',true),'orc','plain',true,'standard',true);leader(demo,1)!.health=1;demo.players[1].deck=[];demo.players[1].hand=[];demo.matchId='qa-'+Date.now();demo=applyAction(demo,{kind:'mulligan',indexes:[]});demo=applyAction(demo,{kind:'mulligan',indexes:[]});for(let n=0;n<1600&&demo.winner===undefined;n++)demo=applyAction(demo,chooseAI(demo,'normal'));startMatch({state:demo,opts:{...opts,mode:'ai',rewardEligible:true}});finished();}}]);}
// Phones: tapping the arena closes an open card preview so it never hides the targets.
document.addEventListener('pointerdown',e=>{if(matchMedia('(pointer: coarse)').matches&&(e.target as HTMLElement).closest?.('#board'))document.querySelector('#card-detail')?.remove();},true);
